#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
One-shot pipeline: video -> light recipe -> WLED.

Steps, all in one command:
    1. write-guard check (must be unlocked in 办公模式)
    2. extract key frames from the video (ffmpeg) -- or use supplied frames
    3. sample the FOUR EDGES of every frame + dominant colors
    4. build a time-ordered multi-color palette + per-edge colours
    5. upload the palette (optional), apply the recipe, save a named preset
    6. optionally configure master/slave sync so every device follows
    7. verify the device state and write the recipe JSON into recipes/

Usage:
    python3 scripts/apply_video_recipe.py <video_url_or_path> --scene "Sunset Ocean"
    python3 scripts/apply_video_recipe.py clip.mp4 --scene "Aurora" --count 10 --mode scene
    python3 scripts/apply_video_recipe.py --frames f1.jpg f2.jpg --scene "Jasmine"
    python3 scripts/apply_video_recipe.py clip.mp4 --scene "X" --sync --ips 192.168.2.9,192.168.2.10
    python3 scripts/apply_video_recipe.py clip.mp4 --scene "X" --palette-mode edge   # no palette upload

Output: JSON with {success, scene, recipe, applied, preset_id, sync, verified}
"""
import json
import os
import sys
import time
from datetime import datetime

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
RECIPES_DIR = os.path.join(SKILL_DIR, "recipes")
sys.path.insert(0, SCRIPT_DIR)

from analyze_video import analyze_video, analyze_video_frames
from apply_recipe import apply_recipe, get_wled_ip, wled_request, load_config


def _save_recipe_file(recipe, preset_id=None, palette_id=None, palette_file_index=None,
                      edge_offsets=None, output=None):
    """Persist the recipe (with recall metadata) into recipes/."""
    recipe = dict(recipe)
    recipe["created_at"] = datetime.now().isoformat(timespec="seconds")
    if preset_id:
        recipe["preset_id"] = preset_id
    if palette_id is not None:
        recipe["palette_id"] = palette_id            # runtime palette ID (or None)
    if palette_file_index is not None:
        recipe["palette_file_index"] = palette_file_index  # /palette{N}.json we wrote
    if edge_offsets is not None:
        recipe["edge_offsets"] = edge_offsets

    if not output:
        safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in recipe.get("name", "scene").lower())
        os.makedirs(RECIPES_DIR, exist_ok=True)
        output = os.path.join(RECIPES_DIR, "{}_{}.json".format(
            safe, datetime.now().strftime("%Y%m%d_%H%M%S")))
    with open(output, "w", encoding="utf-8") as f:
        json.dump(recipe, f, indent=2, ensure_ascii=False)
    return output


def custom_palette_id(ip, file_index):
    """Map a /palette{N}.json file index to its runtime palette ID.

    WLED 16.x palette ID space (wled00/const.h):
        0   .. FIXED_PALETTE_COUNT-1 (=71)  built-in palettes
        72  .. 200                          user custom palettes,
                                            file index 0 -> ID 200, growing DOWN
        201 .. 255                          usermod palettes

    So uploading palette1.json does NOT give you palette 1 (that is the built-in
    "Random Cycle"); it gives you ID 199, and only after a reboot. The device
    reports palcount (fixed + custom) and cpalcount (custom) in /json/info, so
        fixed = palcount - cpalcount
        base  = fixed + cpalmax - 1
    Returns None when the device cannot be read.
    """
    info = wled_request(ip, "/json/info", method="GET", timeout=3)
    if not isinstance(info, dict):
        return None
    palcount = info.get("palcount")
    cpalcount = info.get("cpalcount")
    cpalmax = info.get("cpalmax")
    if palcount is None or cpalcount is None or cpalmax is None:
        return None
    fixed = palcount - cpalcount
    if fixed <= 0 or cpalmax <= 0:
        return None
    return fixed + cpalmax - 1 - file_index


def _try_upload_palette(palette_data, palette_id):
    """Upload the custom palette; report the runtime ID and whether it is live.

    `palette_id` here is the FILE index (`/palette{index}.json`). The runtime ID
    it will occupy is returned as `runtime_id`, because that - not the file
    index - is what a segment's `pal` field must point at.
    """
    try:
        from upload_palette import upload_palette
        res = upload_palette(palette_id, palette_data)
    except Exception as exc:
        return {"success": False, "message": "palette upload failed: {}".format(exc)}

    ip = get_wled_ip()
    res["file_index"] = palette_id
    res["runtime_id"] = custom_palette_id(ip, palette_id)

    # A freshly written palette{N}.json is only picked up at boot, so confirm
    # against the palette names the device actually reports right now.
    visible = False
    names = wled_request(ip, "/json/pal", method="GET")
    if isinstance(names, list):
        visible = any("custom" in str(n).lower() for n in names)
    res["visible_without_reboot"] = bool(visible)
    if not visible:
        res["note"] = ("自定义调色板需重启 WLED 后才会出现在 ID {} 上；"
                       "本次已回退为每段 col 直写（pal=0），画面不受影响。".format(res.get("runtime_id")))
    return res


def apply_video_recipe(video=None, frames=None, scene="Video Scene", count=8, mode="even",
                       palette_mode="palette", save_preset=True, setup_sync=False,
                       sync_ips=None, band_ratio=0.12, output=None, reboot_palette=False,
                       takeover=None):
    """One-shot pipeline: video -> key frames -> four-edge colours -> WLED.

    takeover: "auto" | "on" | "off" — how hard to fight for the strip when an
    external realtime stream (screen sync etc.) is running. See
    apply_recipe.stop_udp_realtime() for the measured behaviour.
    """
    config = load_config()

    # ---- 0. write guard -------------------------------------------------
    from guard import require_write
    blocked = require_write(config=config, action="apply_video_recipe")
    if blocked:
        return blocked

    # ---- 1/2/3/4. analysis ---------------------------------------------
    if frames:
        analysis = analyze_video_frames(frames, scene, config=config, band_ratio=band_ratio)
    else:
        analysis = analyze_video(video, scene, count=count, mode=mode, config=config)
    if not analysis.get("success"):
        return {"success": False, "stage": "analyze", "detail": analysis}

    recipe = analysis["recipe"]
    ip = get_wled_ip()
    if not ip:
        return {"success": False, "stage": "discover",
                "message": "WLED IP not configured. Run discover_wled.py first"}

    # ---- 5. palette -----------------------------------------------------
    palette_info = {"mode": palette_mode}
    palette_id = None          # runtime ID persisted into the recipe
    palette_file_index = None  # /palette{N}.json index we wrote
    if palette_mode == "palette" and recipe.get("palette_data"):
        palette_file_index = int((config.get("video", {}) or {}).get("palette_id", 1))
        up = _try_upload_palette(recipe["palette_data"], palette_file_index)
        palette_info["upload"] = up
        if up.get("success") and not up.get("visible_without_reboot") and reboot_palette:
            # WLED only reads /palette*.json at boot; `rb` is the API reboot.
            wled_request(ip, "/json/state", method="POST", data={"rb": True})
            time.sleep(12)
            palette_info["rebooted"] = True
            up2 = _try_upload_palette(recipe["palette_data"], palette_file_index)
            palette_info["upload_after_reboot"] = up2
            up = up2
        usable = up.get("success") and up.get("visible_without_reboot") and up.get("runtime_id") is not None
        if usable:
            # Must point at the RUNTIME id, not the file index: palette1.json is
            # palette ID 199 on WLED 16.x, while ID 1 is built-in "Random Cycle".
            palette_id = up["runtime_id"]
            recipe["pal"] = palette_id
        else:
            recipe["pal"] = 0
            palette_info["fallback"] = (
                "自定义调色板需重启后才会出现在 ID {}{}；本次已用每段 col 直写（pal=0）交付，"
                "画面与颜色不受影响。".format(
                    up.get("runtime_id"), "" if up.get("runtime_id") is not None else "(未知)")
                + (" 加 --allow-reboot 可在写入前自动重启以启用调色板。"
                   if not palette_info.get("rebooted") else ""))
    else:
        recipe["pal"] = 0
    palette_info["file_index"] = palette_file_index
    palette_info["runtime_id"] = palette_id

    # ---- 5b. four-edge offsets (spread the palette across the edges) ----
    edge_offsets = {"top": 0, "right": 64, "bottom": 128, "left": 192}
    recipe["edge_offsets"] = edge_offsets

    # ---- 5c. apply ------------------------------------------------------
    # takeover="auto": exit realtime, and seize the realtime override (lor=2)
    # only when an external stream would otherwise keep owning the strip.
    apply_res = apply_recipe(recipe, takeover=takeover)
    if not apply_res.get("success"):
        return {"success": False, "stage": "apply", "detail": apply_res,
                "analysis": analysis.get("message")}

    # ---- 5d. save named preset -----------------------------------------
    preset_id = None
    preset_res = None
    if save_preset:
        try:
            from save_preset import find_free_preset_id, save_preset as save_preset_fn
            storage = config.get("recipe_storage", {})
            preset_id = find_free_preset_id(ip, storage.get("preset_id_start", 100),
                                            storage.get("preset_id_end", 250))
            if preset_id:
                pr = save_preset_fn(preset_id, scene)
                preset_res = pr
                if not pr.get("success"):
                    preset_id = None
        except Exception as exc:
            preset_id = None
            apply_res.setdefault("warnings", []).append("preset save skipped: {}".format(exc))

    # ---- 6. sync --------------------------------------------------------
    sync_res = None
    if setup_sync:
        try:
            from sync_devices import setup_sync as setup_sync_fn
            sync_res = setup_sync_fn(ips=sync_ips, master=ip)
        except Exception as exc:
            sync_res = {"success": False, "message": "sync setup failed: {}".format(exc)}

    # ---- 7. verify + persist -------------------------------------------
    time.sleep(0.4)
    verify = wled_request(ip, "/json/state", method="GET")
    verify_info = wled_request(ip, "/json/info", method="GET", timeout=3)
    verify_fps = (verify_info.get("leds") or {}).get("fps") if isinstance(verify_info, dict) else None
    segs = [s for s in verify.get("seg", []) if s.get("len", 0) > 0]
    recipe_file = _save_recipe_file(recipe, preset_id=preset_id, palette_id=palette_id,
                                    palette_file_index=palette_file_index,
                                    edge_offsets=edge_offsets, output=output)

    warnings = list(apply_res.get("warnings", []))
    if preset_res is not None and not preset_res.get("verified"):
        warnings.append("预设未能落盘：{}".format(preset_res.get("message")))

    result = {
        "success": True,
        "scene": scene,
        "ip": ip,
        "video": video,
        "frame_count": analysis.get("frame_count"),
        "edge_colors_hex": analysis.get("edge_colors_hex"),
        "palette_colors_hex": analysis.get("palette_colors_hex"),
        "palette": palette_info,
        "fx": recipe.get("fx"),
        "sx": recipe.get("sx"),
        "ix": recipe.get("ix"),
        "bri": recipe.get("bri"),
        "pal": recipe.get("pal"),
        "preset_id": preset_id,
        "preset_verified": bool(preset_res.get("verified")) if preset_res else None,
        "recipe_file": recipe_file,
        "realtime": apply_res.get("realtime"),
        "sync": sync_res,
        "verified": {
            "on": verify.get("on"),
            "live": verify.get("live"),
            "lor": verify.get("lor"),
            "fps": verify_fps,
            "segments": len(segs),
            "seg0": {"fx": segs[0].get("fx"), "sx": segs[0].get("sx"),
                     "ix": segs[0].get("ix"), "pal": segs[0].get("pal"),
                     "col": (segs[0].get("col") or [[None]])[0]} if segs else None,
        },
        "message": "Video recipe '{}' applied (fx={}, {} segments, preset={}).".format(
            scene, recipe.get("fx"), len(segs), preset_id),
    }
    if warnings:
        result["warnings"] = warnings
    return result


def main():
    if "--help" in sys.argv or "-h" in sys.argv or len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    video = None
    frames = []
    scene = "Video Scene"
    count = 8
    mode = "even"
    palette_mode = "palette"
    save_preset = "--no-preset" not in sys.argv
    setup_sync = "--sync" in sys.argv
    sync_ips = None
    band_ratio = 0.12
    output = None
    reboot_palette = "--allow-reboot" in sys.argv
    json_only = "--json" in sys.argv
    takeover = None

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--scene" and i + 1 < len(sys.argv):
            scene = sys.argv[i + 1]; i += 2
        elif arg == "--count" and i + 1 < len(sys.argv):
            count = int(sys.argv[i + 1]); i += 2
        elif arg == "--takeover" and i + 1 < len(sys.argv):
            takeover = sys.argv[i + 1]; i += 2  # else fall back to config.realtime.takeover
        elif arg == "--mode" and i + 1 < len(sys.argv):
            mode = sys.argv[i + 1]; i += 2
        elif arg == "--palette-mode" and i + 1 < len(sys.argv):
            palette_mode = sys.argv[i + 1]; i += 2
        elif arg == "--ips" and i + 1 < len(sys.argv):
            sync_ips = [x.strip() for x in sys.argv[i + 1].split(",") if x.strip()]; i += 2
        elif arg == "--band" and i + 1 < len(sys.argv):
            band_ratio = float(sys.argv[i + 1]); i += 2
        elif arg == "--output" and i + 1 < len(sys.argv):
            output = sys.argv[i + 1]; i += 2
        elif arg == "--frames":
            i += 1
            while i < len(sys.argv) and not sys.argv[i].startswith("--"):
                frames.append(sys.argv[i]); i += 1
        elif arg in ("--json", "--sync", "--no-preset", "--allow-reboot"):
            i += 1
        elif not arg.startswith("--") and video is None:
            video = arg; i += 1
        else:
            i += 1

    if not video and not frames:
        print(json.dumps({"success": False, "message": "Provide a video path/URL or --frames ..."},
                         ensure_ascii=False))
        sys.exit(1)

    result = apply_video_recipe(video=video, frames=frames or None, scene=scene, count=count,
                                mode=mode, palette_mode=palette_mode, save_preset=save_preset,
                                setup_sync=setup_sync, sync_ips=sync_ips, band_ratio=band_ratio,
                                output=output, reboot_palette=reboot_palette, takeover=takeover)

    if not json_only and result.get("success"):
        print("Scene: {}  (preset {})".format(scene, result.get("preset_id")))
        print("Edge colors: {}".format(json.dumps(result.get("edge_colors_hex", {}), ensure_ascii=False)))
        print("Palette: {}".format(", ".join(result.get("palette_colors_hex", []))))
        v = result.get("verified") or {}
        print("Strip: live={} lor={} fps={} preset_saved={}".format(
            v.get("live"), v.get("lor"), v.get("fps"), result.get("preset_verified")))
        for w in result.get("warnings", []) or []:
            print("WARN: {}".format(w))
        print("--- JSON ---")
    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
